package com.findupto.voicepos

import android.content.Context
import android.util.Base64
import java.io.File

private const val DEFAULT_NAME="The Slice Of Heaven"
private const val DEFAULT_ADDRESS="Old Utility Store near Police Line Khansar Road Bhakkar Punjab Pakistan"
private const val DEFAULT_PHONE="0332 1872929, 0310 3685151"

class Store(private val context:Context){
 private val p=context.getSharedPreferences("voice_pos_v5",Context.MODE_PRIVATE)
 init{CurrencySettings.symbol=p.getString("currency_symbol","Rs")?:"Rs";if(!p.getBoolean("defaults_initialized",false))p.edit().putString("name",p.getString("name","")?.ifBlank{DEFAULT_NAME}?:DEFAULT_NAME).putString("address",p.getString("address","")?.ifBlank{DEFAULT_ADDRESS}?:DEFAULT_ADDRESS).putString("phone",p.getString("phone","")?.ifBlank{DEFAULT_PHONE}?:DEFAULT_PHONE).putBoolean("defaults_initialized",true).apply()}
 fun cash()=p.getString("cash","0")!!.toDoubleOrNull()?:0.0;fun setCash(v:Double)=p.edit().putString("cash",v.toString()).apply();fun hasOpeningCash()=p.getBoolean("opening",false);fun setOpeningCash(v:Double){setCash(v);p.edit().putBoolean("opening",true).apply()}
 fun profile()=CompanyProfile(p.getString("name",DEFAULT_NAME)!!.ifBlank{DEFAULT_NAME},p.getString("address",DEFAULT_ADDRESS)!!.ifBlank{DEFAULT_ADDRESS},p.getString("phone",DEFAULT_PHONE)!!.ifBlank{DEFAULT_PHONE},p.getString("footer","Thank you for your visit")!!,p.getString("logo_path","")!!,p.getBoolean("sale_logo",true),p.getBoolean("kitchen_logo",true),p.getString("currency_symbol","Rs")!!,p.getString("currency_code","PKR")!!,p.getBoolean("tax_enabled",false),p.getString("tax_rate","0")!!.toDoubleOrNull()?:0.0,p.getString("tax_label","Tax")!!,p.getBoolean("service_enabled",false),p.getString("service_rate","0")!!.toDoubleOrNull()?:0.0,p.getString("service_label","Service Charge")!!).also{CurrencySettings.symbol=it.currencySymbol}
 fun saveProfile(x:CompanyProfile)=p.edit().putString("name",x.name).putString("address",x.address).putString("phone",x.phone).putString("footer",x.footer).putString("logo_path",x.logoPath).putBoolean("sale_logo",x.saleLogoEnabled).putBoolean("kitchen_logo",x.kitchenLogoEnabled).putString("currency_symbol",x.currencySymbol).putString("currency_code",x.currencyCode).putBoolean("tax_enabled",x.taxEnabled).putString("tax_rate",x.taxRate.toString()).putString("tax_label",x.taxLabel).putBoolean("service_enabled",x.serviceChargeEnabled).putString("service_rate",x.serviceChargeRate.toString()).putString("service_label",x.serviceChargeLabel).apply().also{CurrencySettings.symbol=x.currencySymbol}
 fun theme()=runCatching{ReceiptTheme.valueOf(p.getString("theme","MODERN")!!)}.getOrDefault(ReceiptTheme.MODERN);fun setTheme(t:ReceiptTheme)=p.edit().putString("theme",t.name).apply();fun customerPrinterAddress()=p.getString("customer_printer","")?:"";fun kitchenPrinterAddress()=p.getString("kitchen_printer","")?:"";fun setCustomerPrinterAddress(v:String)=p.edit().putString("customer_printer",v).apply();fun setKitchenPrinterAddress(v:String)=p.edit().putString("kitchen_printer",v).apply()
 fun serviceCharge(x:Double):Double{val q=profile();return if(q.serviceChargeEnabled)x*q.serviceChargeRate/100.0 else 0.0}
 fun tax(x:Double):Double{val q=profile();val b=x+serviceCharge(x);return if(q.taxEnabled)b*q.taxRate/100.0 else 0.0}
 fun totalWithTax(x:Double)=x+serviceCharge(x)+tax(x)
 private fun enc(s:String)=s.replace("~","%7E");private fun dec(s:String)=s.replace("%7E","~");private fun ei(xs:List<SaleItem>)=xs.joinToString("|"){"${it.name.replace("~"," ").replace("|"," ")}^${it.qty}^${it.price}"};private fun di(s:String)=s.split("|").filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("^");SaleItem(a[0],a[1].toInt(),a[2].toDouble())}.getOrNull()}
 fun sales()=p.getString("sales","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Sale(a[0].toLong(),di(a[1]),a[2].toDouble(),a[3].toLong(),dec(a.getOrNull(4).orEmpty()),dec(a.getOrNull(5).orEmpty()),a.getOrNull(6)?:"DINE_IN",dec(a.getOrNull(7).orEmpty()),a.getOrNull(8)?:"CASH",a.getOrNull(9)?.toDoubleOrNull()?:a[2].toDouble(),a.getOrNull(10)?.toDoubleOrNull()?:0.0,a.getOrNull(11)?.toLongOrNull()?:0L,a.getOrNull(12)?.toDoubleOrNull()?:0.0,a.getOrNull(13)?.toDoubleOrNull()?:0.0)}.getOrNull()}
 private fun saveSales(xs:List<Sale>)=p.edit().putString("sales",xs.joinToString("\n"){"${it.id}~${ei(it.items)}~${it.total}~${it.time}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.orderType}~${enc(it.customerAddress)}~${it.paymentMethod}~${it.paidAmount}~${it.dueAmount}~${it.shiftId}~${it.serviceCharge}~${it.tax}"}).apply()
 fun addSale(s:Sale){saveSales(sales()+s);if(s.paidAmount>0)addPayment(PaymentRecord(System.currentTimeMillis(),s.id,s.paidAmount,s.paymentMethod,System.currentTimeMillis(),s.shiftId));if(s.dueAmount>0)addDue(DueAccount(s.id,s.id,s.customerName,s.customerPhone,s.total,s.paidAmount,s.time))};fun updateSale(s:Sale)=saveSales(sales().map{if(it.id==s.id)s else it})
 fun pending()=p.getString("pending","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");PendingSale(a[0].toLong(),di(a[1]),a[2].toLong(),dec(a.getOrNull(3).orEmpty()),dec(a.getOrNull(4).orEmpty()),a.getOrNull(5)?:"DINE_IN",dec(a.getOrNull(6).orEmpty()))}.getOrNull()};private fun savePending(xs:List<PendingSale>)=p.edit().putString("pending",xs.joinToString("\n"){"${it.id}~${ei(it.items)}~${it.time}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.orderType}~${enc(it.customerAddress)}"}).apply();fun addPending(s:PendingSale)=savePending(pending()+s);fun replacePending(s:PendingSale)=savePending(pending().map{if(it.id==s.id)s else it});fun removePending(id:Long)=savePending(pending().filterNot{it.id==id})
 fun menu()=p.getString("menu","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("^");MenuItem(a[0].toLong(),a[1],a[2].toDouble(),a.getOrNull(3)?:"",a.getOrNull(4)?:"")}.getOrNull()};fun saveMenu(xs:List<MenuItem>)=p.edit().putString("menu",xs.joinToString("\n"){"${it.id}^${it.name.replace("^"," ")}^${it.price}^${it.variant.replace("^"," ")}^${it.size.replace("^"," ")}"}).apply();fun addMenuItem(i:MenuItem)=saveMenu(menu()+i);fun updateMenuItem(i:MenuItem)=saveMenu(menu().map{if(it.id==i.id)i else it});fun removeMenuItem(id:Long)=saveMenu(menu().filterNot{it.id==id})
 fun expenses()=p.getString("expenses","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Expense(a[0].toLong(),a[1],a[2],a[3].toDouble(),a[4].toLong(),a.getOrNull(5)?:"CASH",a.getOrNull(6)?.toLongOrNull()?:0L)}.getOrNull()};fun addExpense(e:Expense)=p.edit().putString("expenses",(expenses()+e).joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply();fun updateExpense(e:Expense)=p.edit().putString("expenses",expenses().map{if(it.id==e.id)e else it}.joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply();fun removeExpense(id:Long)=p.edit().putString("expenses",expenses().filterNot{it.id==id}.joinToString("\n"){"${it.id}~${it.title.replace("~"," ")}~${it.category.replace("~"," ")}~${it.amount}~${it.time}~${it.paymentMethod}~${it.shiftId}"}).apply()
 fun shifts()=p.getString("shifts","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");Shift(a[0].toLong(),dec(a[1]),a[2].toLong(),a[3].toDouble(),a.getOrNull(4)?.toLongOrNull()?:0L,a.getOrNull(5)?.toDoubleOrNull()?:0.0,a.getOrNull(6)?:"OPEN")}.getOrNull()};private fun saveShifts(xs:List<Shift>)=p.edit().putString("shifts",xs.joinToString("\n"){"${it.id}~${enc(it.person)}~${it.openedAt}~${it.openingCash}~${it.closedAt}~${it.closingCash}~${it.status}"}).apply();fun activeShift()=shifts().lastOrNull{it.status=="OPEN"};fun openShift(person:String,cash:Double):Shift{activeShift()?.let{closeShift(it.id,cash)};val s=Shift(System.currentTimeMillis(),person,System.currentTimeMillis(),cash);saveShifts(shifts()+s);return s};fun closeShift(id:Long,cash:Double)=saveShifts(shifts().map{if(it.id==id)it.copy(closedAt=System.currentTimeMillis(),closingCash=cash,status="CLOSED")else it});fun shiftSales(id:Long)=sales().filter{it.shiftId==id};fun shiftExpenses(id:Long)=expenses().filter{it.shiftId==id}
 fun payments()=p.getString("payments","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");PaymentRecord(a[0].toLong(),a[1].toLong(),a[2].toDouble(),a[3],a[4].toLong(),a[5].toLong(),dec(a.getOrNull(6).orEmpty()))}.getOrNull()};private fun addPayment(x:PaymentRecord)=p.edit().putString("payments",(payments()+x).joinToString("\n"){"${it.id}~${it.saleId}~${it.amount}~${it.method}~${it.time}~${it.shiftId}~${enc(it.note)}"}).apply();fun expectedShiftCash(id:Long):Double{val s=shifts().firstOrNull{it.id==id}?:return 0.0;return s.openingCash+payments().filter{it.shiftId==id&&it.method=="CASH"}.sumOf{it.amount}-shiftExpenses(id).filter{it.paymentMethod=="CASH"}.sumOf{it.amount}}
 fun dues()=p.getString("dues","")!!.lines().filter{it.isNotBlank()}.mapNotNull{runCatching{val a=it.split("~");DueAccount(a[0].toLong(),a[1].toLong(),dec(a[2]),dec(a[3]),a[4].toDouble(),a[5].toDouble(),a[6].toLong())}.getOrNull()}.filter{it.balance>0.005};private fun saveDues(xs:List<DueAccount>)=p.edit().putString("dues",xs.joinToString("\n"){"${it.id}~${it.saleId}~${enc(it.customerName)}~${enc(it.customerPhone)}~${it.total}~${it.paid}~${it.createdAt}"}).apply();private fun addDue(x:DueAccount)=saveDues(dues()+x);fun recordPayment(dueId:Long,amount:Double,method:String,shiftId:Long):Boolean{val d=dues().firstOrNull{it.id==dueId}?:return false;val pay=amount.coerceIn(0.0,d.balance);if(pay<=0)return false;addPayment(PaymentRecord(System.currentTimeMillis(),d.saleId,pay,method,System.currentTimeMillis(),shiftId,"Due payment"));saveDues(dues().map{if(it.id==d.id)it.copy(paid=it.paid+pay)else it});sales().firstOrNull{it.id==d.saleId}?.let{val paid=it.paidAmount+pay;updateSale(it.copy(paidAmount=paid,dueAmount=(it.total-paid).coerceAtLeast(0.0)))};return true}
 fun paymentTotals(start:Long=0L,end:Long=Long.MAX_VALUE)=payments().filter{it.time in start..end}.groupBy{it.method}.mapValues{it.value.sumOf(PaymentRecord::amount)};fun productTotals(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.flatMap{it.items}.groupBy{it.name}.mapValues{it.value.sumOf(SaleItem::qty)}.toList().sortedByDescending{it.second};fun grossSales(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.sumOf{it.total};fun realizedSales(start:Long=0L,end:Long=Long.MAX_VALUE)=sales().filter{it.time in start..end}.sumOf{it.paidAmount};fun dueTotal()=dues().sumOf{it.balance};fun totalExpenses(start:Long=0L,end:Long=Long.MAX_VALUE)=expenses().filter{it.time in start..end}.sumOf{it.amount}
 private fun itemsJson(xs:List<SaleItem>)=org.json.JSONArray().apply{xs.forEach{put(org.json.JSONObject().apply{put("name",it.name);put("qty",it.qty);put("price",it.price)})}};private fun saleJson(s:Sale)=org.json.JSONObject().apply{put("id",s.id);put("time",s.time);put("total",s.total);put("customerName",s.customerName);put("customerPhone",s.customerPhone);put("orderType",s.orderType);put("customerAddress",s.customerAddress);put("paymentMethod",s.paymentMethod);put("paidAmount",s.paidAmount);put("dueAmount",s.dueAmount);put("shiftId",s.shiftId);put("serviceCharge",s.serviceCharge);put("tax",s.tax);put("items",itemsJson(s.items))};private fun pendingJson(s:PendingSale)=org.json.JSONObject().apply{put("id",s.id);put("time",s.time);put("customerName",s.customerName);put("customerPhone",s.customerPhone);put("orderType",s.orderType);put("customerAddress",s.customerAddress);put("items",itemsJson(s.items))}
 fun exportBackup():String{val r=org.json.JSONObject();val q=profile();r.put("format","VOICE_POS_BACKUP_V5");r.put("cash",cash());r.put("opening",hasOpeningCash());r.put("theme",theme().name);r.put("profile",org.json.JSONObject().apply{put("name",q.name);put("address",q.address);put("phone",q.phone);put("footer",q.footer);put("saleLogo",q.saleLogoEnabled);put("kitchenLogo",q.kitchenLogoEnabled);put("logo",q.logoPath.takeIf{it.isNotBlank()}?.let{runCatching{Base64.encodeToString(File(it).readBytes(),Base64.NO_WRAP)}.getOrDefault("")}?:"");put("currencySymbol",q.currencySymbol);put("currencyCode",q.currencyCode);put("taxEnabled",q.taxEnabled);put("taxRate",q.taxRate);put("taxLabel",q.taxLabel);put("serviceEnabled",q.serviceChargeEnabled);put("serviceRate",q.serviceChargeRate);put("serviceLabel",q.serviceChargeLabel)});r.put("menu",org.json.JSONArray().apply{menu().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("name",it.name);put("price",it.price);put("variant",it.variant);put("size",it.size)})}});r.put("sales",org.json.JSONArray().apply{sales().forEach{put(saleJson(it))}});r.put("pending",org.json.JSONArray().apply{pending().forEach{put(pendingJson(it))}});r.put("expenses",org.json.JSONArray().apply{expenses().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("title",it.title);put("category",it.category);put("amount",it.amount);put("time",it.time);put("paymentMethod",it.paymentMethod);put("shiftId",it.shiftId)})}});r.put("shifts",org.json.JSONArray().apply{shifts().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("person",it.person);put("openedAt",it.openedAt);put("openingCash",it.openingCash);put("closedAt",it.closedAt);put("closingCash",it.closingCash);put("status",it.status)})}});r.put("dues",org.json.JSONArray().apply{dues().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("saleId",it.saleId);put("customerName",it.customerName);put("customerPhone",it.customerPhone);put("total",it.total);put("paid",it.paid);put("createdAt",it.createdAt)})}});r.put("payments",org.json.JSONArray().apply{payments().forEach{put(org.json.JSONObject().apply{put("id",it.id);put("saleId",it.saleId);put("amount",it.amount);put("method",it.method);put("time",it.time);put("shiftId",it.shiftId);put("note",it.note)})}});return r.toString()}
 private fun ja(a:org.json.JSONArray)= (0 until a.length()).map{val x=a.getJSONObject(it);SaleItem(x.getString("name"),x.getInt("qty"),x.getDouble("price"))}
 fun importBackup(raw:String){val r=org.json.JSONObject(raw);require(r.optString("format").startsWith("VOICE_POS_BACKUP_V"));val q=r.getJSONObject("profile");var lp=profile().logoPath;val b=q.optString("logo","");if(b.isNotBlank())runCatching{val f=File(context.filesDir,"branding/company_logo.png");f.parentFile?.mkdirs();f.writeBytes(Base64.decode(b,Base64.DEFAULT));lp=f.absolutePath};saveProfile(CompanyProfile(q.optString("name",DEFAULT_NAME),q.optString("address",DEFAULT_ADDRESS),q.optString("phone",DEFAULT_PHONE),q.optString("footer","Thank you for your visit"),lp,q.optBoolean("saleLogo",true),q.optBoolean("kitchenLogo",true),q.optString("currencySymbol","Rs"),q.optString("currencyCode","PKR"),q.optBoolean("taxEnabled",false),q.optDouble("taxRate",0.0),q.optString("taxLabel","Tax"),q.optBoolean("serviceEnabled",false),q.optDouble("serviceRate",0.0),q.optString("serviceLabel","Service Charge")));setCash(r.optDouble("cash",0.0));p.edit().putBoolean("opening",r.optBoolean("opening",true)).putString("theme",r.optString("theme","MODERN")).apply();val m=r.optJSONArray("menu")?:org.json.JSONArray();saveMenu((0 until m.length()).map{val x=m.getJSONObject(it);MenuItem(x.getLong("id"),x.getString("name"),x.getDouble("price"),x.optString("variant"),x.optString("size"))});val s=r.optJSONArray("sales")?:org.json.JSONArray();saveSales((0 until s.length()).map{val x=s.getJSONObject(it);Sale(x.getLong("id"),ja(x.getJSONArray("items")),x.getDouble("total"),x.getLong("time"),x.optString("customerName"),x.optString("customerPhone"),x.optString("orderType","DINE_IN"),x.optString("customerAddress"),x.optString("paymentMethod","CASH"),x.optDouble("paidAmount",x.getDouble("total")),x.optDouble("dueAmount",0.0),x.optLong("shiftId",0L),x.optDouble("serviceCharge",0.0),x.optDouble("tax",0.0))});val e=r.optJSONArray("expenses")?:org.json.JSONArray();p.edit().putString("expenses",(0 until e.length()).joinToString("\n"){val x=e.getJSONObject(it);"${x.getLong("id")}~${x.getString("title")}~${x.getString("category")}~${x.getDouble("amount")}~${x.getLong("time")}~${x.optString("paymentMethod","CASH")}~${x.optLong("shiftId",0L)}"}).apply();val d=r.optJSONArray("dues")?:org.json.JSONArray();p.edit().putString("dues",(0 until d.length()).joinToString("\n"){val x=d.getJSONObject(it);"${x.getLong("id")}~${x.getLong("saleId")}~${enc(x.optString("customerName"))}~${enc(x.optString("customerPhone"))}~${x.getDouble("total")}~${x.getDouble("paid")}~${x.getLong("createdAt")}"}).apply();val sh=r.optJSONArray("shifts")?:org.json.JSONArray();p.edit().putString("shifts",(0 until sh.length()).joinToString("\n"){val x=sh.getJSONObject(it);"${x.getLong("id")}~${enc(x.optString("person"))}~${x.getLong("openedAt")}~${x.getDouble("openingCash")}~${x.optLong("closedAt",0L)}~${x.optDouble("closingCash",0.0)}~${x.optString("status","OPEN")}"}).apply();val py=r.optJSONArray("payments")?:org.json.JSONArray();p.edit().putString("payments",(0 until py.length()).joinToString("\n"){val x=py.getJSONObject(it);"${x.getLong("id")}~${x.getLong("saleId")}~${x.getDouble("amount")}~${x.getString("method")}~${x.getLong("time")}~${x.getLong("shiftId")}~${enc(x.optString("note"))}"}).apply()}
}
